              releaseTitle: item.title || 'Release',
              artist: artistName,
              artUrl: item.artUrl || '',
              artistBioPicUrl: globalBioUrl,
              allImages: [],
              isFree: true,
              isNyp: false,
              isPurchased: false,
              isPaid: false,
